/**
 * @suppress
 */
public object FfiConverterTypeTollgateMobileNode: FfiConverter<TollgateMobileNode, Pointer> {

    override fun lower(value: TollgateMobileNode): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): TollgateMobileNode {
        return TollgateMobileNode(value)
    }

    override fun read(buf: ByteBuffer): TollgateMobileNode {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: TollgateMobileNode) = 8UL

    override fun write(value: TollgateMobileNode, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



/**
 * One observation from the consume loop, surfaced to the UI each poll.
 */
data class ConsumeEvent (
    /**
     * 0 = the initial "start" event, then 1, 2, … per poll.
     */
    var `poll`: kotlin.UInt, 
    var `peerPubkey`: kotlin.String, 
    var `price`: PriceView, 
    var `paidScaled`: kotlin.ULong, 
    /**
     * Signed remaining balance: `+` prepaid credit left, `−` provider owes us.
     */
    var `remainingScaled`: kotlin.Long, 
    var `report`: ReportSummary?, 
    /**
     * The peer reported us balance-exhausted (cut off).
     */
    var `cutOff`: kotlin.Boolean, 
    /**
     * We sent a top-up this poll.
     */
    var `toppedUp`: kotlin.Boolean
) {
    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeConsumeEvent: FfiConverterRustBuffer<ConsumeEvent> {
    override fun read(buf: ByteBuffer): ConsumeEvent {
        return ConsumeEvent(
            FfiConverterUInt.read(buf),
            FfiConverterString.read(buf),
            FfiConverterTypePriceView.read(buf),
            FfiConverterULong.read(buf),
            FfiConverterLong.read(buf),
            FfiConverterOptionalTypeReportSummary.read(buf),
            FfiConverterBoolean.read(buf),
            FfiConverterBoolean.read(buf),
        )
    }

    override fun allocationSize(value: ConsumeEvent) = (
            FfiConverterUInt.allocationSize(value.`poll`) +
            FfiConverterString.allocationSize(value.`peerPubkey`) +
            FfiConverterTypePriceView.allocationSize(value.`price`) +
            FfiConverterULong.allocationSize(value.`paidScaled`) +
            FfiConverterLong.allocationSize(value.`remainingScaled`) +
            FfiConverterOptionalTypeReportSummary.allocationSize(value.`report`) +
            FfiConverterBoolean.allocationSize(value.`cutOff`) +
            FfiConverterBoolean.allocationSize(value.`toppedUp`)
    )

    override fun write(value: ConsumeEvent, buf: ByteBuffer) {
            FfiConverterUInt.write(value.`poll`, buf)
            FfiConverterString.write(value.`peerPubkey`, buf)
            FfiConverterTypePriceView.write(value.`price`, buf)
            FfiConverterULong.write(value.`paidScaled`, buf)
            FfiConverterLong.write(value.`remainingScaled`, buf)
            FfiConverterOptionalTypeReportSummary.write(value.`report`, buf)
            FfiConverterBoolean.write(value.`cutOff`, buf)
            FfiConverterBoolean.write(value.`toppedUp`, buf)
    }
}



