/**
 * Errors surfaced across the FFI boundary. `reason` is a short human string.
 */
sealed class TollgateException: kotlin.Exception() {
    
    class Network(
        
        override val message: kotlin.String
        ) : TollgateException()
    
    class Protocol(
        
        override val message: kotlin.String
        ) : TollgateException()
    
    class Rejected(
        
        val `reason`: kotlin.String
        ) : TollgateException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class Other(
        
        override val message: kotlin.String
        ) : TollgateException()
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<TollgateException> {
        override fun lift(error_buf: RustBuffer.ByValue): TollgateException = FfiConverterTypeTollgateError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeTollgateError : FfiConverterRustBuffer<TollgateException> {
    override fun read(buf: ByteBuffer): TollgateException {
        

        return when(buf.getInt()) {
            1 -> TollgateException.Network(
                FfiConverterString.read(buf),
                )
            2 -> TollgateException.Protocol(
                FfiConverterString.read(buf),
                )
            3 -> TollgateException.Rejected(
                FfiConverterString.read(buf),
                )
            4 -> TollgateException.Other(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: TollgateException): ULong {
        return when(value) {
            is TollgateException.Network -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is TollgateException.Protocol -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is TollgateException.Rejected -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is TollgateException.Other -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
        }
    }

    override fun write(value: TollgateException, buf: ByteBuffer) {
        when(value) {
            is TollgateException.Network -> {
                buf.putInt(1)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is TollgateException.Protocol -> {
                buf.putInt(2)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is TollgateException.Rejected -> {
                buf.putInt(3)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is TollgateException.Other -> {
                buf.putInt(4)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalUInt: FfiConverterRustBuffer<kotlin.UInt?> {
    override fun read(buf: ByteBuffer): kotlin.UInt? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterUInt.read(buf)
    }

    override fun allocationSize(value: kotlin.UInt?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterUInt.allocationSize(value)
        }
    }

    override fun write(value: kotlin.UInt?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterUInt.write(value, buf)
        }
    }
}




